297		ledgerPath := setupOutputFailLedger(t)
298		r := runCLIWith(t, []string{"submit", "-l", ledgerPath}, outputFailBatch)
299		if r.code != 0 {
300			t.Fatalf("code=%d err=%s", r.code, r.err)
301		}
302		if !strings.Contains(r.out, `"insufficient_balance"`) || !strings.HasSuffix(r.out, "\n") {
